	@Test
	void usesReleasableNativeRunsAndFallsBackToHeapComparisonSort() throws Exception {
		try (ExternalLongTupleSorter nativeSorter = new ExternalLongTupleSorter(temporaryDirectory, "native", 3,
				1024, 3, BulkCodec.FAST)) {
			assertThat(nativeSorter.usesNativeBuffer()).isTrue();
		}

		try (ExternalLongTupleSorter fallback = new ExternalLongTupleSorter(temporaryDirectory, "fallback", 3, 48L, 3,
				BulkCodec.FAST, (arena, bytes) -> {
					throw new OutOfMemoryError("injected direct-memory pressure");
				})) {
			assertThat(fallback.usesNativeBuffer()).isFalse();
			fallback.add3(-1L, 1L, 2L);
			fallback.add3(0L, 2L, 3L);
			fallback.add3(Long.MIN_VALUE, 0L, 0L);
			fallback.add3(1L, 0L, 0L);

			List<Long> firstColumns = new ArrayList<>();
			fallback.finish(temporaryDirectory.resolve("fallback.bin"))
					.forEach(tuple -> firstColumns.add(tuple[0]));

			assertThat(firstColumns).containsExactly(0L, 1L, Long.MIN_VALUE, -1L);
		}
	}

